import{z as B,x as d,o as r,c as p,q as i,j as s,D as t,d as E,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"超时与退避","description":"","frontmatter":{"title":"超时与退避","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/timeout-backoff.md","filePath":"cs/timeout-backoff.md","lastUpdated":1791063341000}'),A={name:"cs/timeout-backoff.md"};function D(c,a,m,f,u,h){const l=d("Mermaid");return r(),p("div",null,[a[2]||(a[2]=i('<h1 id="超时与退避" tabindex="-1">超时与退避 <a class="header-anchor" href="#超时与退避" aria-label="Permalink to &quot;超时与退避&quot;">​</a></h1><div class="epigraph"><p>超时把「不知道」变成失败。退避让重试错开。没有抖动的同步重试是分布式的惊群，比第一次故障更大。</p><footer>—— 据 Ethernet 的截断二进制指数退避；Dean and Barroso 对重试放大的讨论；Google SRE 实践整理</footer></div><p>上一课<a href="/cs/rate-limit-circuit-breaker">熔断</a>在错误率高时关门。缺口是<strong>门关上之前与半开时</strong>：每次失败立刻重试，下游刚病就被同一波请求再打。本课钉超时选择与指数退避加抖动。后课对冲请求是另一类「同一调用多份」，会再放大。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>超时太长：线程与连接被占，尾延迟变过载。超时太短：慢成功被当失败再重试，执行次数上升，接到<a href="/cs/rpc-semantics">RPC 语义</a>。分层超时必须递减：网关 &gt; 服务 &gt; 下游，否则下层还在跑上层已重试。</p><p>退避：第 \\(k\\) 次等 \\(\\min(cap, b^k)\\) 再加随机抖动。无抖动：所有客户端用同一时钟对齐重试——雪崩。Ethernet 很早就用随机退避拆冲突；RPC 重试是同一形状。</p><p><span class="marginnote">SRE 书强调限制重试预算（retry budget），防止一小撮失败客户端吃光下游。这是限流在时间维。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>单调钟量超时，接<a href="/cs/clock-drift">物理时钟</a>。幂等才重试非幂等写。重试预算：一段窗口内重试占比上限。给下游传 deadline，而不是各层各猜。</p>',9)),(r(),s(o,null,{default:t(()=>[n(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%A4%B1%E8%B4%A5%20%2F%20%E8%B6%85%E6%97%B6%22%5D%20--%3E%20B%5B%22%E6%8C%87%E6%95%B0%E9%80%80%E9%81%BF%20%2B%20%E6%8A%96%E5%8A%A8%22%5D%0A%20%20B%20--%3E%20BD%5B%22deadline%20%E4%BC%A0%E9%80%92%22%5D%0A%20%20BD%20--%3E%20R%5B%22%E6%9C%89%E9%99%90%E6%AC%A1%E9%87%8D%E8%AF%95%22%5D%0A%20%20R%20--%3E%20CB%5B%22%E4%BB%8D%E5%A4%B1%E8%B4%A5%E5%88%99%E7%86%94%E6%96%AD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"不要在熔断打开时还按原预算重试。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[E("重试放大：失败率 \\(p\\) 时若立即重试一次，负载约 \\(1+p\\)，已病系统 \\(p\\) 上升，正反馈。退避与预算把反馈压住。与"),e("a",{href:"/cs/failure-detectors"},"故障检测器"),E("：超时即怀疑，误伤代价是多余重试，不是脑裂（除非重试的是选主）。")],-1)),a[6]||(a[6]=e("p",null,"这条正反馈回路怎么被三道闸压住：",-1)),(r(),s(o,null,{default:t(()=>[n(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E4%B8%8B%E6%B8%B8%E6%95%85%E9%9A%9C%3A%20%E5%A4%B1%E8%B4%A5%E7%8E%87%20p%22%5D%20--%3E%20RT%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E7%AB%8B%E5%8D%B3%E9%87%8D%E8%AF%95%22%5D%0A%20%20RT%20--%3E%20LOAD%5B%22%E8%B4%9F%E8%BD%BD%E7%BA%A6%201%2Bp%3A%20%E6%9B%B4%E9%AB%98%22%5D%0A%20%20LOAD%20--%3E%20WORSE%5B%22p%20%E4%B8%8A%E5%8D%87%3A%20%E6%9B%B4%E6%85%A2%E6%9B%B4%E7%B3%9F%22%5D%0A%20%20WORSE%20--%3E%20RT%0A%20%20BK%5B%22%E6%8C%87%E6%95%B0%E9%80%80%E9%81%BF%E5%8A%A0%E6%8A%96%E5%8A%A8%22%5D%20-.%E9%94%99%E5%BC%80%E8%AF%B7%E6%B1%82.-%3E%20RT%0A%20%20BB%5B%22%E9%87%8D%E8%AF%95%E9%A2%84%E7%AE%97%E5%B0%81%E9%A1%B6%22%5D%20-.%E9%99%90%E6%80%BB%E9%87%8F.-%3E%20LOAD%0A%20%20DL%5B%22deadline%20%E9%80%92%E5%87%8F%E4%BC%A0%E9%80%92%22%5D%20-.%E6%8E%90%E7%9F%AD%E4%B8%8A%E6%B8%B8%E7%AD%89%E5%BE%85.-%3E%20P%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p><span class="marginnote">数字实例：取底数 \\(b=2\\)、上限 \\(cap=8\\) 秒——第 1 次重试前等约 1 秒上下加随机抖动，第 2 次 2 秒，第 3 次 4 秒，之后封顶 8 秒。用户十次不耐烦的点击，不会变成十次背靠背打到下游的请求。</span></p><p>本课不写 TCP RTO 公式全文。也不把无线 CSMA 当数据中心 RPC 的实现。</p><p>Deadline 传播：剩余时间随 RPC 走，避免「上层 1s、下层 5s」的倒置。这是部分同步里把 \\(\\Delta\\) 写成请求字段。</p><p><span class="marginnote">直觉类比：deadline 传递像外卖订单上的送达倒计时——平台给骑手 30 分钟，骑手留给取餐的只能更少。每层 RPC 拿到的是「剩余时间」，而不是各层自己拍一个新时限，否则会出现上层早已放弃、下层还在苦跑的倒置。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不对冲请求（下一课）。不引入自适应超时的全部估计器（点名：Hedged、percentile）。后课默认：重试必抖动必预算必幂等；超时用单调钟与递减 deadline。尾延迟对冲会故意发第二份，必须算进预算。</p><p>失败后立刻同步重试是把检测器的误伤变成过载。随机化是活性工程，也是安全负载。</p><p><span class="marginnote">常见误区：初学者容易以为「重试次数越多越可靠」——下游已经病了时，每次重试都是给病人加运动量。退避、抖动、预算三者缺一不可：只加抖动不加预算，惊群只是被摊开，打向下游的总量一点没减。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>超时定义「不知道」；太短制造假失败与重复执行。</li><li>指数退避必须加抖动；要有重试预算。</li><li>Deadline 向下传递，层间递减。</li><li>出处：指数退避；Dean–Barroso；SRE 实践。</li></ul>',10))])}const T=B(A,[["render",D]]);export{C as __pageData,T as default};
